    "seo_name": "monterustico",
    "business_name": "Azienda Agricola Monterustico",
    "description": "Monterustico is a dramatic hill, tucked in Farigliano, ten miles away south of Barolo and the Langhe hills. The vineyards here enjoy the proximity of the Tanaro river, only a few hundred feet away, and face the iconic peak of Monviso and the Alpine range, directly to the west. \r\nThere is no shortage of challenges in this land. The untamed landscape and the old farming legacy have been threatened over the years, and many vineyards have already been ripped out. \r\n\r\nImpressed by the potential of this terroir, the Vajras stepped in with a dream to preserve and revive the local heritage and craft true, enticing wines.",
