    "id": 249559,
    "name": "Sassaia",
    "seo_name": "sassaia",
    "business_name": "Sassaia",
    "description": "Sassaia earned the prestigious Falstaff Award for second best white wine in Piedmont for Derthona Timorasso. The wine making style is an innovative twist on tradition which combines Burgundian best practices, Italian terroir and collaboration between Enrico, Pierre Naigeon and Walter Massa. Our Capriata d’Orba winery was redesigned and modernized to adopt Pierre Naigeon’s Burgundian style augmented with knowledge earned from UC Davis enology program.\r\n\r\nHand Harvest: \r\nOur first selection begins early morning, surrounded by cool temperatures, where trained harvesters choose only the best fruit for vinification.\r\n\r\nGrapes arrive in small 6kg crates:\r\nWe purposely choose small crates to avoid crushing berries which permits us to chill the fruit for extended skin contact in a temperature controlled environment for 24-48 hours prior to a second hand sorting. Historically, these crates are typically used for air dried wine styles.\r\n\r\nHand Sorting:\r\nAfter a complete inspection, only the best grapes make the final selection. We do not use any corkscrew system to push grapes into the press. Grapes are hand introduced to the press to avoid breaking stems and crushing seeds.\r\n\r\nGravity:\r\nJuice is introduced to barrel via gravity for low temperature slow spontaneous fermentation. Science and technology serve as our guide to feed fermentations, monitor aging and reduce racking.",
