    "name": "Ricasoli",
    "seo_name": "ricasoli",
    "business_name": "Barone Ricasoli",
    "description": "Barone Ricasoli – a name that has been synonymous with wine since 1141 – is the fourth oldest company in the world still runned by its founding family and the first in Italy in the field of wine. The estate extends for over 1,200 hectares – the largest in Chianti Classico- of which 235 hectares planted to vine and 26 hectares of olive groves. Francesco Ricasoli -32nd Baron, current owner and managing director- has been running the family firm since 1993, with the aim of breathing new life into the quality and personality of the great wines of Brolio, experimenting and highlighting the unique features of the territory and its history. The wines and other products created at Brolio can be tasted and purchased in the elegant wineshop, while the nearby osteria offers a chance to experience the most authentic flavours of local gastronomic traditions.",
