    "description": "The story of Ricossa is a story of loyalty to territory and tradition, a blend of resourcefulness, professionalism, and dedication which transformed a small provincial distillery into an international brand. The Ricossa family were the owners of an award winning distillery at the end of the 1800's on the outskirts of Asti in the region of Piedmont. <br>Nearly a century later, we continue the Ricossa story mixing Italian tradition with innovation for the production of quality wine. We source grapes for our products and value our strong collaboration with local farmers. All our grapes are grown and harvested throughout Piedmont.",
