    "description": "Stags’ Leap Winery was founded in 1893 by Horace Chase and his wife Minnie Mizner Chase; the daughter of a prominent San Franciscan who was a U.S. Senator and Ambassador to Central America. The Chase’s named their 240-acre-estate Stags’ Leap, and the mountains behind the property came to be called The Stags Leap Palisades. In addition to establishing the old stone winery, the Chase’s built the estate Manor House, excavated the first wine storage caves on the east side of Napa Valley, and installed what is thought to be the first in-ground fresh water swimming pool in Northern California. \r\n\r\nStags’ Leap became a beloved destination for San Francisco Society, attracting prominent politicians, artists and writers. Those who have owned the Stags’ Leap estate have taken it upon themselves to be stewards; committed to maintaining the rich natural heritage of this charmed micro-valley. Most remarkable among these individuals was Mrs. Francis Grange, who acquired Stags’ Leap in 1913. She carefully transformed the property into a working ranch and Napa Valley pre-eminent resort. After the Grange era, the winery and Manor House fell into disrepair but wine production began again in 1971 when the property was purchased by Carl Doumani and underwent a vast restoration. \r\n\r\nToday, Stags’ Leap winery continues the tradition of hospitality and stewardship. As one of California’s earliest wine estates, the unique terroir and ideal microclimate supports a classical standard of viticulture, land use, and winemaking that is as relevant today as it was over a century ago.\r\n\r\nWinemaker Christophe Paubert practices a meticulous, hands-off style of winemaking that emphasizes balance and freshness. The Stags’ Leap estate is about intensely flavored wines, yet soft tannins; balanced winemaking brings these qualities to the bottle.\r\n\r\nFrom the hand-picked and hand-sorted fruit to the oak barrel aging in caves, carved out of the solid rock of the mountain, Paubert’s methods are simple and traditional. His goal is to convey the essence of this world-class terroir from the grape to the glass, creating handcrafted wines that tell an authentic story of the land on which they are grown.\r\n\r\nStags' Leap is best known for its Cabernet Sauvignons and Petite Sirahs (sourced from Napa Valley and the estate), as well as Chardonnay and Viognier. Within the portfolio are varietal and blended expressions as well as single-vineyard and single-barrel selection wines.",
