    "business_name": "Joseph Phelps Vineyards",
    "description": "Joseph Phelps Vineyards is committed to crafting world class, estate-based wines for fifty years. Founded in 1973 when Joe Phelps purchased a former cattle ranch near St. Helena in the Napa Valley, the winery now controls and farms over 400 acres of vines on nine estate vineyards in St. Helena, the Stags Leap District, Oakville, Rutherford, Oak Knoll District, Carneros and South Napa Valley. In 1999, Phelps added 100 acres of vineyard property near the town of Freestone on the Sonoma Coast, where Pinot Noir and Chardonnay are now grown.  Phelps is best known for its flagship Napa Valley blend of red Bordeaux varieties, Insignia, first produced in 1974.  Awarded Wine Spectator’s “Wine of the Year” in 2005, Insignia is widely regarded as a qualitative benchmark for California winemaking.",
