    "business_name": "Shafer Vineyards",
    "description": "Shafer Vineyards is a historic Napa Valley estate renowned for producing elegant, world-class wines for more than 45 years. Legendary wine critic Robert Parker named Shafer “one of the world’s greatest wineries\".\r\n\r\nShafer Vineyards was established in 1973 by the Shafer family, who produced their first vintage in 1978. The hillside estate itself has a history of grape-growing and winemaking that reaches back in time to 1880.\r\n\r\nShafer’s legendary winemaker, Elias Fernandez, and his team oversee 242 acres of estate vineyards as well as wine production. Elias has been making wine at Shafer since 1984.\r\n\r\nThe Shafer portfolio includes five elegant, world-class wines: Red Shoulder Ranch Chardonnay, TD-9 Cabernet Sauvignon, One Point Five Cabernet Sauvignon, Relentless, and Hillside Select Cabernet Sauvignon\r\n\r\nShafer offers guests The Hillside Select Experience, which includes four vintages of Hillside Select going back 20 years in age as well as an exploration of the hillside estate with stunning Napa Valley views.\r\n\r\nShafer offers guests The Private Collectors Experience, an elevated tasting of Shafer’s wines including two vintages of Hillside Select.",
