    "id": 1780,
    "name": "CHANDON California",
    "seo_name": "chandon-california",
    "business_name": "CHANDON California",
    "description": "Pioneers of American Sparkling Wine.\r\n\r\nIn 1973, CHANDON brought the pioneering spirit of a Champagne house to California, establishing its winery in Napa Valley, one of America’s most celebrated wine regions.\r\n\r\nThe story began in 1968, when Robert-Jean de Vogüé, inspired by the quality of Californian wines he discovered, saw an opportunity for CHANDON to lead the way as the first Champagne-house-led sparkling wine venture in the United States. He recruited John Wright, a passionate oenophile and expert on Californian wines, to bring this vision to life.\r\n\r\nWright carefully selected exceptional sites across Los Carneros, Mt Veeder and Yountville, each offering distinctive altitudes, aspects and microclimates ideally suited to sparkling-wine grapes. Planting began soon after, with the first harvest taking place in 1976 under winemaker Dawnine Dyer and renowned oenologist Edmond Maudière.\r\n\r\nToday, CHANDON Napa Valley continues this pioneering legacy, crafting award-winning sparkling wines that combine French winemaking heritage with the distinctive character of California. CHANDON has become a leading sparkling wine brand in the US market, continuing to explore new possibilities in American sparkling wine.",
