    "id": 808,
    "name": "Biltmore Winery",
    "seo_name": "biltmore-winery",
    "business_name": "Biltmore Winery",
    "description": "George Vanderbilt was known as a thoughtful collector of wines, and Biltmore wines reflect the legacy of gracious hospitality that he offered his guests more than a century ago. While Mr. Vanderbilt introduced the pleasures of wine to Biltmore, it was his grandson, William A.V. Cecil, who had the vision and determination to take Biltmore’s agricultural tradition and re-imagine it as vineyards and a winery for his family’s estate. The tradition continues today as they welcome their guests to Biltmore’s Winery to discover the fruits of their labor.\r\n\r\nEstablished in 1985, Biltmore’s Winery is a state-of-the-art facility housed in an original estate dairy barn, allowing their guests to connect with their long agricultural history and their winemaking philosophy of creating excellent wines that are approachable, true to varietal character, and consistent from vintage to vintage.\r\n\r\nFrom the Blue Ridge Mountains of Western North Carolina to their local growers and partner vineyards in California and Washington, Biltmore selects the finest grapes to handcraft their wines at the estate where they welcome guests to savor classic varietals and discover new favorites.\r\n\r\nWhether you prefer red, white, rosé, or sparkling wines, Biltmore wines offer delightful options for every taste and every occasion. They produce approximately 150,000 cases each year, and you can enjoy their wines in the Tasting Room at the Winery, adjacent Wine Bar, and in their estate restaurants. In addition, you can find Biltmore wines at local retailers in the southeast, and they ship to 40 states, so you can stock up online. Become a member of their Vanderbilt Wine Club® to enjoy seasonal shipments delivered to your door.\r\n\r\nIn addition to the care they take in crafting their fine wines, they also incorporate sustainable practices like a cork recycling program and soil erosion techniques in their vineyard. Throughout the winemaking process, they turn natural materials such as crushed grape skins into compost that provides fodder for estate wildlife.",
